  font-family: 'Archivist Noto Sans';
  font-style: normal;
  font-weight: 400;
  font-stretch: 100%;
  font-display: swap;
  src: url(data:font/woff2;base64,) format('woff2');
  unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;
}
@font-face {
  font-family: 'Archivist Noto Sans';
  font-style: normal;
  font-weight: 700;
  font-stretch: 100%;
  font-display: swap;
  src: url(data:font/woff2;base64,) format('woff2');
  unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;
}

:root {

  --d5e-parchment: #f0ddbd;
  --d5e-parchment-dark: #f4e4c1;
  --d5e-parchment-light: #fef8ee;

  --d5e-text-dark: #191813;
  --d5e-text-accent: #7a200d;

  --d5e-bar-fill: #922610;
  --d5e-bar-stroke: #922610;

  --d5e-border-tan: #d9c484;
  --d5e-border-tan-light: #e8dcc0;
  --d5e-border-tan-dark: #c4a95e;

  --d5e-shadow: 0 4px 24px rgba(134, 116, 83, 0.3), 0 2px 8px rgba(134, 116, 83, 0.2);
  --d5e-shadow-light: 0 2px 8px rgba(134, 116, 83, 0.2);
  --d5e-shadow-heavy: 0 6px 32px rgba(134, 116, 83, 0.4);

  --stat-block-bg: var(--d5e-parchment);
  --stat-block-text: var(--d5e-text-dark);
  --stat-block-header: var(--d5e-text-accent);
  --stat-block-bar: var(--d5e-bar-fill);
  --stat-block-border: var(--d5e-border-tan);
  --stat-block-shadow: var(--d5e-shadow);
  --stat-block-padding: 0.6em;
  --stat-block-section-gap: 0.3em;
}

.cm-embed-block:has(.archivist-side-btns) .edit-block-button {
  cursor: pointer;
}

.cm-embed-block:has(.archivist-side-btns):hover > .edit-block-button,
.cm-embed-block:has(.archivist-side-btns):focus-within > .edit-block-button {
  opacity: 1;
}

.cm-embed-block:has(.archivist-side-btns):focus-within,
.archivist-compendium-ref:focus-within {
  outline: 1px solid var(--interactive-accent);
  border-radius: var(--radius-s);
}

.archivist-block-delete-btn {
  position: absolute;
  padding: var(--size-2-2) var(--size-2-3);
  top: calc(var(--size-2-2) + 28px);
  inset-inline-end: var(--size-2-2);
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-s);
  cursor: pointer;
  color: var(--text-muted);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.15s, color 0.15s, background 0.15s;
  z-index: 10;
}

.archivist-block-delete-btn.archivist-block-delete-btn-monster {
  top: calc(var(--size-2-2) + 56px);
}

.archivist-block-delete-btn svg {
  width: 18px;
  height: 18px;
  stroke-width: 1.75;
}

.archivist-side-btns .archivist-block-column-btn {
  position: static;
  opacity: 1;
  pointer-events: auto;
  padding: 0;
  top: auto;
  inset-inline-end: auto;
}

.archivist-block-column-btn:not(.archivist-side-btn) {
  position: absolute;
  padding: var(--size-2-2) var(--size-2-3);
  top: calc(var(--size-2-2) + 28px);
  inset-inline-end: var(--size-2-2);
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-s);
  cursor: pointer;
  color: var(--text-muted);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.15s, color 0.15s, background 0.15s;
  z-index: 10;
}

.archivist-block-column-btn svg {
  width: 18px;
  height: 18px;
  stroke-width: 1.75;
}

.archivist-block-column-btn:not(.archivist-side-btn):hover {
  color: var(--text-accent);
  background: var(--background-modifier-hover);
}

.cm-embed-block:hover .archivist-block-column-btn:not(.archivist-side-btn),
.cm-embed-block:focus-within .archivist-block-column-btn:not(.archivist-side-btn) {
  opacity: 1;
  pointer-events: auto;
}

.markdown-reading-view .archivist-block-column-btn {
  display: none;
}

.cm-embed-block:hover .archivist-block-delete-btn,
.cm-embed-block:focus-within .archivist-block-delete-btn {
  opacity: 1;
  pointer-events: auto;
}

.archivist-block-delete-btn:hover {
  color: var(--text-error);
  background: var(--background-modifier-hover);
}

.markdown-reading-view .archivist-block-delete-btn {
  display: none;
}

.archivist-monster-block-wrapper {
  position: relative;
  width: 100%;
  max-width: 400px;
  margin: 1.5em auto;
  display: flex;
  justify-content: center;
}

.archivist-monster-block-wrapper.archivist-monster-two-col {
  max-width: none;
  width: calc(100% - 80px);
  justify-content: flex-start;
}

.archivist-monster-two-col-flow {
  column-count: 2;
  column-gap: 16px;
  column-rule: 1px solid var(--d5e-border-tan);
}

.archivist-monster-two-col-flow .property-block,
.archivist-monster-two-col-flow .property-line,
.archivist-monster-two-col-flow .archivist-feature,
.archivist-monster-two-col-flow .abilities-block,
.archivist-monster-two-col-flow .actions-header,
.archivist-monster-two-col-flow .archivist-legendary-intro,
.archivist-monster-two-col-flow .archivist-monster-section,
.archivist-monster-two-col-flow .archivist-legendary-resistance,
.archivist-monster-two-col-flow .archivist-toggle-box-row {
  break-inside: avoid;
  -webkit-column-break-inside: avoid;
}

.archivist-monster-two-col-flow table,
.archivist-monster-two-col-flow blockquote,
.archivist-monster-two-col-flow ul {
  break-inside: avoid;
  -webkit-column-break-inside: avoid;
}
.archivist-monster-block .archivist-monster-token { float: right; max-width: 6em; margin: 0 0 0.4em 0.6em; }
.archivist-monster-block .archivist-monster-token img { max-width: 100%; height: auto; }
.archivist-monster-block .archivist-monster-portrait { margin-top: 0.6em; }
.archivist-monster-block .archivist-monster-portrait img { max-width: 100%; height: auto; }

.archivist-monster-two-col-flow .stat-block-bar {
  break-inside: avoid;
  break-after: avoid;
}

.archivist-monster-block {
  background: var(--stat-block-bg);
  font-family: 'Archivist Noto Sans', 'Noto Sans', 'Myriad Pro', Calibri, Helvetica, Arial, sans-serif;
  font-size: 14px;
  line-height: 1.2em;
  color: var(--stat-block-text);
  position: relative;
  box-shadow: var(--stat-block-shadow);
  padding: var(--stat-block-padding);
  width: 100%;
}

.archivist-monster-block *,
.archivist-spell-block *,
.archivist-item-block * {
  border-color: transparent;
}

.archivist-monster-block h1,
.archivist-monster-block h2,
.archivist-monster-block h3,
.archivist-monster-block h4,
.archivist-monster-block p,
.archivist-spell-block h1,
.archivist-spell-block h2,
.archivist-spell-block h3,
.archivist-spell-block h4,
.archivist-spell-block p,
.archivist-item-block h1,
.archivist-item-block h2,
.archivist-item-block h3,
.archivist-item-block h4,
.archivist-item-block p {
  margin: 0;
  padding: 0;
  border: none;
  font-size: inherit;
  font-weight: inherit;
  font-family: inherit;
  color: inherit;
  line-height: inherit;
  letter-spacing: normal;
}

.archivist-monster-block p + p,
.archivist-monster-block .archivist-feature-entry > p {
  margin-top: 0.5em;
}

.archivist-monster-block .archivist-monster-section[data-fill="markdown"] > :not(.actions-header, table) {
  line-height: 19.6px;
}
.archivist-monster-block .archivist-monster-section[data-fill="markdown"] :is(p, li) {
  font-size: 13px;
}

.archivist-monster-block .stat-block-header {
  margin-bottom: 0.3em;
}

.archivist-monster-block .monster-name {
  font-family:
    'Archivist Libre Baskerville', 'Libre Baskerville', 'Lora', 'Calisto MT', 'Bookman Old Style', Bookman, 'Goudy Old Style', Garamond,
    'Hoefler Text', 'Bitstream Charter', Georgia, serif;
  color: var(--stat-block-header);
  font-size: 25px;
  line-height: 1.2em;
  margin: 0 0 0 -0.02em;
  font-weight: 700;
  letter-spacing: 1px;
  font-variant: small-caps;
}

.archivist-monster-block .monster-type {
  font-style: italic;
  font-weight: normal;
  font-size: 12px;
  line-height: 1.2em;
  margin: 0 0 0.35em;
  color: var(--stat-block-text);
}

.archivist-monster-block .stat-block-bar {
  width: 100%;
  height: 5px;
  margin: 4px 0;
}

.archivist-monster-block .stat-block-bar polyline {
  fill: var(--stat-block-bar);
  stroke: var(--stat-block-bar);
  stroke-width: 1;
}

.archivist-monster-block .property-block {
  padding: 0.3em 0;
}

.archivist-monster-block .property-line {
  line-height: 1.4em;
  margin-bottom: 0.3em;
  text-indent: -1em;
  margin-left: 1em;
}

.archivist-monster-block .property-line.last {
  margin-bottom: 0;
}

.archivist-monster-block .property-line h4 {
  margin: 0;
  color: var(--stat-block-header);
  font-family: 'Archivist Noto Sans', 'Noto Sans', 'Myriad Pro', Calibri, Helvetica, Arial, sans-serif;
  font-size: 13px;
  font-weight: bold;
  font-style: normal;
  font-variant: normal;
  display: inline;
  margin-right: 0.25em;
  border: none;
  padding: 0;
  line-height: inherit;
}

.archivist-monster-block .property-line p {
  margin: 0;
  display: inline;
  font-family: 'Archivist Noto Sans', 'Noto Sans', 'Myriad Pro', Calibri, Helvetica, Arial, sans-serif;
  font-weight: normal;
  font-style: normal;
  font-variant: normal;
  font-size: 13px;
  color: var(--stat-block-text);
}

.archivist-monster-block .property-line h4:after {
  content: '.';
  font-weight: bold;
}

.archivist-monster-block .abilities-block {
  text-align: center;
  color: var(--stat-block-header);
  padding: var(--stat-block-section-gap) 0;
}

.archivist-monster-block .abilities-table {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
  border: none;
  margin: 0;
  background: transparent;
}

.archivist-monster-block .abilities-table th {
  font-weight: bold;
  color: var(--stat-block-header);
  font-size: 14px;
  padding: 0.25em;
  font-family: 'Archivist Noto Sans', 'Noto Sans', sans-serif;
  border: none;
  background: transparent;
  text-align: center;
}

.archivist-monster-block .abilities-table td {
  padding: 0.25em;
  font-size: 14px;
  color: var(--d5e-text-dark);
  border: none;
  background: transparent;
  text-align: center;
}

.archivist-monster-block .abilities-table tr {
  border: none;
  background: transparent;
}

.archivist-monster-block .abilities-table thead tr {
  border: none;
  background: transparent;
}

.archivist-monster-block .abilities-table tr:hover {
  background: transparent;
}

.archivist-monster-block .ability-score {
  font-weight: normal;
}

.archivist-monster-block .ability-modifier {
  font-weight: normal;
}

.archivist-stat-tag {
  display: inline;
  white-space: nowrap;
}

.archivist-tag-nobreak {
  white-space: nowrap;
}
.archivist-stat-tag-icon {
  display: inline;
  margin-right: 2px;
}
.archivist-stat-tag-icon svg {
  width: 14px;
  height: 14px;
  vertical-align: -2px;
  display: inline;
}

.archivist-stat-tag-dice,
.archivist-stat-tag-damage {
  color: #922610;
  border-bottom: 1px dotted transparent;
  cursor: pointer;
}
.archivist-stat-tag-dice:hover,
.archivist-stat-tag-damage:hover {
  color: #7a1a08;
  border-bottom-color: currentColor;
}
.archivist-stat-tag-atk {
  color: #7a200d;
  font-style: italic;
  cursor: pointer;
  border-bottom: 1px dotted transparent;
}
.archivist-stat-tag-atk:hover {
  border-bottom-color: currentColor;
}

.archivist-stat-tag.pc-roll-flash,
.archivist-tag.pc-roll-flash {
  border-radius: 4px;
  box-shadow: 0 0 0 2px var(--pc-parchment-light, var(--background-primary)), 0 0 0 4px var(--pc-crimson, #922610);
}
.archivist-stat-tag-dc {
  color: #191813;
}
.archivist-stat-tag-dc .archivist-stat-tag-icon svg {
  color: #555;
}

.archivist-monster-block .actions-header {
  font-family:
    'Archivist Libre Baskerville', 'Libre Baskerville', 'Lora', 'Calisto MT', 'Bookman Old Style', Bookman, 'Goudy Old Style', Garamond,
    'Hoefler Text', 'Bitstream Charter', Georgia, serif;
  font-size: 23px;
  font-weight: normal;
  font-style: normal;
  font-variant: small-caps;
  letter-spacing: 1px;
  color: var(--stat-block-header);
  margin: 0.45em 0 0.1em;
  border-bottom: 1px solid var(--stat-block-header);
  padding-bottom: 0.15em;
  display: block;
}

.archivist-monster-block .action-description {
  font-style: italic;
}

.archivist-monster-block .legendary-intro,
.archivist-monster-block p.archivist-legendary-intro,
.archivist-legendary-intro {
  font-style: italic;
  margin: 0.25em 0 0.5em;
  text-indent: 0;
  margin-left: 0;
  font-size: 13px;
  line-height: 1.4em;
}

.dnd-formatted-text {
  display: inline;
}

.dnd-formatted-text .inline-icon {
  display: inline-block;
  width: 14px;
  height: 14px;
  vertical-align: middle;
  margin-right: 2px;
}

.dnd-formatted-text .dice-roll {
  color: #191813;
  font-weight: normal;
}

.dnd-formatted-text .dice-roll .inline-icon {
  color: #7a200d;
}

.dnd-formatted-text .dc-check {
  color: #191813;
  font-weight: normal;
}

.dnd-formatted-text .dc-check .inline-icon {
  color: #7a200d;
}

.dnd-formatted-text .chance-roll {
  color: #191813;
  font-weight: normal;
}

.dnd-formatted-text .chance-roll .inline-icon {
  color: #7a200d;
}

.dnd-formatted-text .attack-type {
  font-style: italic;
  color: #191813;
}

.dnd-formatted-text .to-hit {
  color: #7a200d;
  font-weight: normal;
}

.dnd-formatted-text .hit-label {
  color: #7a200d;
  font-style: italic;
}

.archivist-spell-block-wrapper {
  position: relative;
  width: calc(100% - 80px);
  margin: 1.5em auto;
  display: flex;
  justify-content: flex-start;
}

.archivist-spell-block,
.archivist-item-block,
.archivist-class-block {
  background: var(--stat-block-bg);
  font-family: 'Archivist Noto Sans', 'Noto Sans', 'Myriad Pro', Calibri, Helvetica, Arial, sans-serif;
  font-size: 14px;
  color: #191813;
  box-shadow:
    0 4px 24px rgba(134, 116, 83, 0.3),
    0 2px 8px rgba(134, 116, 83, 0.2);
  padding: 0.6em;
  border-radius: 4px;
}

.archivist-spell-block {
  line-height: 1.2em;
  position: relative;
  width: 100%;
}

.archivist-spell-block .spell-block-header {
  margin-bottom: 0.3em;
  border-bottom: 2px solid #7a200d;
  padding-bottom: 0.3em;
}

.archivist-spell-block .spell-name {
  font-family:
    'Archivist Libre Baskerville', 'Libre Baskerville', 'Lora', 'Calisto MT', 'Bookman Old Style', Bookman, 'Goudy Old Style', Garamond,
    'Hoefler Text', 'Bitstream Charter', Georgia, serif;
  color: #7a200d;
  font-size: 23px;
  line-height: 1.2em;
  margin: 0 0 0.1em -0.02em;
  font-weight: 700;
  letter-spacing: 1px;
}

.archivist-spell-block .spell-school {
  font-style: italic;
  font-size: 14px;
  color: #191813;
  margin-top: 0.2em;
}

.archivist-spell-block .spell-properties {
  margin: 0.4em 0;
  padding: 0.4em 0;
  border-bottom: 1px solid #d9c484;
}

.archivist-spell-block .property-line {
  display: flex;
  align-items: center;
  gap: 0.5em;
  margin: 0.2em 0;
  font-size: 13px;
}

.archivist-spell-block .property-icon {
  width: 14px;
  height: 14px;
  color: #7a200d;
  flex-shrink: 0;
}

.archivist-spell-block .property-label {
  font-weight: 600;
  color: #191813;
  flex-shrink: 0;
}

.archivist-spell-block .property-value {
  color: #191813;
}

.archivist-spell-block .spell-description {
  margin: 0.6em 0;
  line-height: 1.4em;
}

.archivist-spell-block .description-paragraph {
  margin: 0.4em 0;
  text-align: justify;
  text-indent: 1em;
}

.archivist-spell-block .description-paragraph:first-child {
  text-indent: 0;
}

.archivist-condition-block .archivist-condition-effects {
  margin: 0.6em 0 0;
  padding: 0.4em 0 0 1.2em;
  border-top: 1px solid #d9c484;
  line-height: 1.4em;
}

.archivist-spell-block .spell-higher-levels {
  margin-top: 0.6em;
  padding-top: 0.4em;
  border-top: 1px solid #d9c484;
}

.archivist-spell-block .higher-levels-header {
  font-weight: 700;
  font-style: italic;
  color: #191813;
  margin-bottom: 0.2em;
}

.archivist-spell-block .spell-classes {
  display: flex;
  align-items: center;
  gap: 0.5em;
  margin-top: 0.6em;
  padding-top: 0.4em;
  border-top: 1px solid #d9c484;
  font-size: 12px;
  color: #666;
}

.archivist-spell-block .classes-list {
  font-style: italic;
  color: #6b5e4b;
}

.archivist-spell-block .spell-classes .classes-more {
  appearance: none;
  display: inline;
  height: auto;
  margin: 0;
  padding: 0 0 0 0.6em;
  border: none;
  border-radius: 0;
  background: none;
  box-shadow: none;
  font: inherit;
  font-size: 12px;
  font-style: normal;
  font-weight: 600;
  color: #7a200d;
  white-space: nowrap;
  cursor: pointer;
}
.archivist-spell-block .spell-classes .classes-more:hover { text-decoration: underline; text-underline-offset: 2px; }
.archivist-spell-block .spell-classes .classes-more:focus-visible { outline: 1px solid #7a200d; outline-offset: 2px; border-radius: 2px; }

.archivist-race-block .race-traits,
.archivist-background-block .race-traits {
  margin-top: 0.6em;
  padding-top: 0.4em;
  border-top: 1px solid #d9c484;
}

.archivist-race-block .race-trait,
.archivist-background-block .race-trait {
  margin: 0.4em 0;
  line-height: 1.4em;
}

.archivist-race-block .race-trait-name,
.archivist-background-block .race-trait-name {
  font-family:
    'Archivist Libre Baskerville', 'Libre Baskerville', 'Lora', 'Calisto MT', 'Bookman Old Style', Bookman, 'Goudy Old Style', Garamond,
    'Hoefler Text', 'Bitstream Charter', Georgia, serif;
  font-weight: 700;
  color: #7a200d;
  display: block;
}

.archivist-spell-block a.internal-link,
.archivist-item-block a.internal-link,
.archivist-class-block a.internal-link,
.archivist-monster-block a.internal-link {
  color: #7a200d;
  text-decoration: underline;
  text-decoration-style: dotted;
